arguments.query:
CREATE TABLE IF NOT EXISTS todos (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, status TEXT DEFAULT 'pending', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS todo_deps (todo_id TEXT NOT NULL, depends_on TEXT NOT NULL, PRIMARY KEY (todo_id, depends_on));
INSERT OR REPLACE INTO todos (id, title, description, status, updated_at) VALUES ('build-notification-form', 'Build notification form page', 'Create a standalone React-style HTML page with a modern form section containing a required radio-button group and submit button in index.html.', 'in_progress', CURRENT_TIMESTAMP);

