        box-shadow: 0 18px 28px rgba(79, 70, 229, 0.22);
        cursor: pointer;
        transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
      }

      .submit-button:hover {
        transform: translateY(-1px);
        filter: brightness(1.02);
      }

      .submit-button:focus-visible {
        outline: 3px solid rgba(79, 70, 229, 0.24);
        outline-offset: 3px;
      }

      .status-message {
        min-height: 1.5em;
        color: var(--brand-strong);
        font-weight: 600;
      }

      @media (max-width: 640px) {
        .hero,
        .form-section {
          padding-inline: 24px;
        }
      }
    </style>
  </head>
  <body>
    <div id="app"></div>
    <script>
      const options = [
        {
          id: "notification-email",
          value: "Email",
          description: "Receive updates in your inbox."
        },
        {
          id: "notification-sms",
          value: "SMS",
          description: "Get quick text message alerts."
        },
        {
          id: "notification-push",
          value: "Push Notifications",
          description: "Stay up to date with mobile push alerts."
        }
      ];

      const escapeHtml = (value) =>
        value
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#39;");

      const RadioOption = ({ id, value, description }) => `
        <label class="radio-card" for="${escapeHtml(id)}">
          <input id="${escapeHtml(id)}" type="radio" name="notificationPreference" value="${escapeHtml(value)}" required />
          <span class="radio-copy">
            <span class="radio-title">${escapeHtml(value)}</span>
            <span class="radio-description">${escapeHtml(description)}</span>
          </span>
        </label>
      `;

      const FormSection = () => `
        <section class="card" aria-labelledby="page-title">
          <header class="hero">
            <span class="eyebrow">Preference Center</span>
            <h1 id="page-title">Choose your ideal notification experience.</h1>
            <p>Select one delivery method so product updates, reminders, and announcements reach you the way you prefer.</p>
          </header>
          <div class="form-section">
            <form id="notification-form">
              <div class="form-field">
                <p class="field-label" id="notification-question">How do you prefer to receive notifications?</p>
                <p class="field-help">Pick one option to continue.</p>
                <div class="radio-group" role="radiogroup" aria-labelledby="notification-question">
                  ${options.map((option) => RadioOption(option)).join("")}
                </div>
              </div>
              <div class="actions">
                <button class="submit-button" type="submit">Submit</button>
                <output class="status-message" id="form-status" aria-live="polite"></output>
              </div>
            </form>
          </div>
        </section>
      `;

      const App = () => `
        <main class="app-shell">
          ${FormSection()}
        </main>
      `;

      document.getElementById("app").innerHTML = App();

      const form = document.getElementById("notification-form");
      const status = document.getElementById("form-status");
      const radioCards = Array.from(document.querySelectorAll(".radio-card"));

      const syncSelectedState = () => {
        radioCards.forEach((card) => {
          const input = card.querySelector("input");
          card.classList.toggle("selected", input.checked);
        });
      };

      form.addEventListener("change", syncSelectedState);
      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const data = new FormData(form);
        const selection = data.get("notificationPreference");
        status.textContent = selection ? `Preference saved: ${selection}.` : "";
      });

      syncSelectedState();
    </script>
  </body>
</html>
